            ["common.readmore"]="Read more",["common.learnmore"]="Learn more",["common.explore"]="Explore",["common.contact"]="Contact us",["common.back"]="Back to home",["common.minread"]="min read",["common.readstory"]="Read story",["common.exploredestinations"]="Explore destinations",
            ["home.eyebrow"]="SKOPJE · WEEKEND NOTES",["home.heroTitleFirst"]="Four places",["home.heroTitleSecond"]="worth the trip.",["home.heroDescription"]="Hidden MK is a small page about Macedonia. For now it is Galicnik, Pelister, Prespa and Matka, plus a few day plans and short texts.",["home.exploreHidden"]="See the four places",["home.findAdventure"]="Filter the day plans",["home.scrollExplore"]="SCROLL",["home.idea"]="WHY THIS SITE",["home.introTitle"]="Ohrid and the old bazaar are not the whole country.",["home.introDescription"]="If you have a free Saturday, the interesting part usually starts after the highway. These are the notes we wish we had the first time: the road, the walk, and where to eat after.",["home.ourStory"]="About the site",["home.startExploring"]="ON THE SITE",["home.discoverDifferentFirst"]="The places",["home.discoverDifferentSecond"]="we wrote up.",["home.viewAllDestinations"]="All four places",["home.mountains"]="MOUNTAINS",["home.galicnikDescription"]="Stone houses above Mavrovo. The road up is slow.",["home.wildNature"]="WILD NATURE",["home.pelisterDescription"]="Pine forest and a long walk. Take water.",["home.waterNature"]="WATER & NATURE",["home.prespaDescription"]="Quieter than Ohrid, if you are done with the crowds.",["home.canyons"]="CANYONS",["home.matkaDescription"]="About 20 minutes from Skopje. Boat, cave, or just the path.",["home.explore"]="Explore",["home.nextAdventure"]="IF YOU ARE NOT SURE",["home.whereNextFirst"]="Pick a kind",["home.whereNextSecond"]="of day.",["home.adventureDescription"]="The rows on the right open a filter. On the experiences page you can also mix category, time and how hard the day should be.",["home.nature"]="Nature",["home.culture"]="Culture",["home.adventure"]="Adventure",["home.foodStories"]="Food & Stories",["home.travelDifferently"]="NOT A TOUR",["home.goBeyondFirst"]="You still organise",["home.goBeyondSecond"]="the transport yourself.",["home.experienceDescription"]="This is not a package with a guide. It is a starting point: where to go, how long it takes, and whether it is realistic if you do not hike every weekend.",["home.curatedExperiences"]="Day plans",["home.localGuides"]="Plain directions",["home.authenticStories"]="Short texts",["home.ofMany"]="of many",["home.stories"]="stories",["home.hiddenPlaces"]="places on the site",["home.guides"]="local guides",["home.uniqueExperiences"]="day plans",["home.country"]="country to discover",["home.fromJournal"]="SHORT TEXTS",["home.storiesRoadFirst"]="From the",["home.storiesRoadSecond"]="notes.",["home.readAllStories"]="All stories",["home.travelGuide"]="NOTES · 5 MIN",["home.localStories"]="VILLAGES · 4 MIN",["home.food"]="FOOD · 4 MIN",["home.readStory"]="Read story",["home.story1"]="7 places we actually send people to",["home.story2"]="The villages above Mavrovo",["home.story3"]="Five dishes, and where you find them",["home.yourStory"]="IF YOU ARE IN SKOPJE",["home.readyToDiscoverFirst"]="Matka is the",["home.readyToDiscoverSecond"]="easy one to start with.",["home.finalDescription"]="The canyon is close. The other three need a bit more time.",["home.planAdventure"]="Contact",
            ["discover.eyebrow"]="WHERE TO START",["discover.title"]="Four kinds of day.",["discover.subtitle"]="Pick one and open the list.",["discover.beyond"]="ON THIS SITE",["discover.looking"]="What do you feel like?",["discover.lookingText"]="The boxes go to places, stories or the day plans. Nothing here is booked through us.",["discover.nature"]="Nature",["discover.natureText"]="Mountains, lakes, forests, caves and landscapes waiting to be explored.",["discover.exploreNature"]="Explore nature",["discover.culture"]="Culture",["discover.cultureText"]="Villages, traditions, history and stories passed from one generation to another.",["discover.discoverCulture"]="Discover culture",["discover.food"]="Food & Local Life",["discover.foodText"]="Traditional dishes, local producers and the people behind Macedonia’s food culture.",["discover.taste"]="Taste Macedonia",["discover.adventure"]="Adventure",["discover.adventureText"]="Hiking, kayaking, camping and experiences designed for curious explorers.",["discover.findAdventure"]="Find an adventure",["discover.how"]="IF IT HELPS",["discover.howTitle"]="We usually do it like this.",["discover.howText"]="There is no account and no basket.",["discover.step1"]="Pick a mood",["discover.step1Text"]="Nature, a village, food, or a longer walk.",["discover.step2"]="Read the practical bit",["discover.step2Text"]="The road, the time, and whether Sunday will be packed.",["discover.step3"]="Go, or change the plan",["discover.step3Text"]="If the filter comes back empty, drop one option.",["discover.start"]="THE PLACES",["discover.places"]="The four we wrote up.",["discover.viewAll"]="View all destinations",["discover.finalEyebrow"]="OR SKIP THE READING",["discover.finalTitle"]="Use the filter.",["discover.finalText"]="Category, length and difficulty. It only searches the four day plans.",
["story.1.title"]="7 places we actually send people to",["story.1.category"]="Travel Guide",["story.1.excerpt"]="Only four of them have a full page here. The other three are still on the list.",["story.1.author"]="HIDDEN MK Editorial",["story.1.date"]="September 12, 2026",["story.1.content"]="This started as a note on a phone. It is not a full guide.\n\n1. Galicnik, above Mavrovo. July has the Galichka svadba, but a normal weekend is enough. The road from Mavrovo is narrow.\n\n2. Lazaropole, nearby and easier to walk around. There is a big church and a view over the valley.\n\n3. Janche is smaller. People stop for the view. Do not expect a restaurant on every corner.\n\n4. Kokino, near Kumanovo. It is a short walk on a rocky hill, not a hike. Go early in summer.\n\n5. Zrze monastery, on a cliff near Prilep. A normal car is fine.\n\n6. Mariovo, south of Prilep. Villages, fields, and long gaps between stops. Bring food.\n\n7. Kratovo. Towers, and a canyon right under the town. Half a day from Skopje is enough.\n\nFull pages so far: Galicnik, Pelister, Prespa, Matka. The rest are notes until we go again.",["story.2.title"]="The villages above Mavrovo",["story.2.category"]="Local Stories",["story.2.excerpt"]="Galicnik for the houses, Lazaropole if you want to walk without a plan.",["story.2.author"]="Elena Petrova",["story.2.date"]="August 28, 2026",["story.2.content"]="We keep sending people to the same two villages, and then they ask about a third.\n\nGalicnik is the one with the stone houses and the wedding in July. Outside that weekend a lot of houses are shut. That is normal. Do not plan a big dinner there.\n\nLazaropole is the one where you can actually wander. The church is obvious, the view is the point, and you can be back in Mavrovo for food.\n\nJanche is the extra stop if you still have daylight. It is small. If a door is closed, it is closed.\n\nSleep in Mavrovo unless you already know someone with a key. The road up is the part that takes longer than the map suggests.",["story.3.title"]="Five dishes, and where you find them",["story.3.category"]="Food",["story.3.excerpt"]="Not a ranking. Just what people actually order, and in which part of the country.",["story.3.author"]="Ana Stojanovska",["story.3.date"]="August 14, 2026",["story.3.content"]="We are not picking a best restaurant. These are dishes, and the regions where you are more likely to see them.\n\nTavche gravche is easy in Skopje. Beans in a clay pot. It is ordinary, which is the point.\n\nAjvar is a September thing, when people roast peppers. The jar from a shop is not the same afternoon.\n\nZelnik and other pita show up in bakeries on the way to Mavrovo. Buy it when you see it. The next village might not have any.\n\nPastrmajlija is more of a Shtip and Veles thing. Do not hunt for it in a mountain village.\n\nShopska and grilled peppers are what you get at a roadside place when you are hungry and the specials are gone. That still counts.",["story.4.title"]="Why this site exists",["story.4.category"]="HIDDEN MK",["story.4.excerpt"]="It started as a faculty project. Then we kept the places we would send a friend to.",["story.4.author"]="HIDDEN MK Editorial",["story.4.date"]="July 30, 2026",["story.4.content"]="We made the site for a faculty project, then kept the places we would actually send a friend to. It is not a booking site.\n\nIf a page is short, that is because we have only been there once. If a road is closed or a kitchen is shut, the contact form is for that.",
            ["about.title"]="Notes from weekends out of Skopje.",["about.eyebrow"]="ABOUT THE SITE",["about.intro"]="Hidden MK started as a site for a course. We picked places in Macedonia that are easy to skip if you only follow the big names.",["about.storyEyebrow"]="OUR STORY",["about.storyTitle"]="We got tired of pages that only show the view.",["about.story1"]="We are in Skopje. Most of the trips here fit in a day or a weekend, by bus or by car.",["about.story2"]="The pages are short on purpose. We would rather say how to get there than write a long text about the view.",["about.story3"]="If you know a place we missed, use the contact form. We read it. There is no call center.",["about.philosophy"]="HOW WE WRITE",["about.philosophyText"]="Write it down.<br />Say how to get there.<br />Do not invent a crowd.",["about.values"]="WHAT IS ON HERE",["about.moreThan"]="What you will actually find.",["about.valuesIntro"]="Not a full map of the country. Just the pages we finished.",["about.value1Title"]="Specific places",["about.value1"]="Four destinations for now. We add a page when we have been there, or when we have checked the road.",["about.value2Title"]="Short stories",["about.value2"]="A few texts about villages and food. Not a magazine.",["about.value3Title"]="Do not trash the place",["about.value3"]="If a trail is marked, stay on it. Matka on Sunday is already crowded enough.",["about.idea"]="FOR NOW",["about.ideaTitle"]="Four places, four day plans, four stories.",["about.ideaText"]="If you live here, you already know some of this. The pages are still useful as a reminder of the road and the season. If you are visiting and you only have a few hours, start with Matka.",
            ["team.title"]="Our Team",["team.eyebrow"]="WHO WRITES THIS",["team.heading"]="The team",["team.intro"]="Four people from Skopje. We split the pages between us.",["team.label"]="OUR TEAM",["team.subtitle"]="Who wrote what.",["team.role1"]="WRITES THE PAGES",["team.bio1"]="Elena writes most of the village pages. She is from Skopje and goes up to Galicnik when the road is open.",["team.role2"]="TRAIL NOTES",["team.bio2"]="Marko checks the walks. If a page says moderate, he means you need proper shoes, not climbing gear.",["team.role3"]="FOOD PAGES",["team.bio3"]="Ana writes the food parts. She cares more about where a dish is from than about making a ranking.",["team.role4"]="PHOTOS",["team.bio4"]="David handles photos. Some pictures are ours, some are still from Wikimedia Commons.",["team.name1"]="Elena Petrova",["team.name2"]="Marko Iliev",["team.name3"]="Ana Stojanovska",["team.name4"]="David Nikolov",["team.join"]="KNOW A PLACE?",["team.joinTitle"]="Send it through the form.",["team.joinText"]="If the road, the food or the hours are wrong, tell us. We would rather fix a page than sound sure.",["team.joinButton"]="Tell us about it",
            ["contact.title"]="Contact",["contact.eyebrow"]="WRITE TO US",["contact.hero"]="A question, a correction, or a place.",["contact.heroText"]="The form comes to us. We read it on weekdays.",["contact.label"]="CONTACT HIDDEN MK",["contact.heading"]="Same people who wrote the pages.",["contact.text"]="Email works too. The phone is for weekdays, and sometimes we are on a bus.",["contact.email"]="Email",["contact.based"]="Based in",["contact.available"]="Available",["contact.hours"]="Monday – Friday, 10:00 – 16:00",["contact.phone"]="Phone",["contact.phoneNumber"]="+389 78 221 640",["contact.errName"]="Please write your name.",["contact.errEmail"]="Please write an email.",["contact.errEmailBad"]="That email does not look right.",["contact.errMessage"]="Please write a message.",["contact.errShort"]="A bit longer than that, at least 10 characters.",["contact.follow"]="FOLLOW THE JOURNEY",["contact.send"]="SEND A MESSAGE",["contact.formHeading"]="The form",["contact.name"]="Your name",["contact.emailPlaceholder"]="you@example.com",["contact.subject"]="Subject",["contact.subjectPlaceholder"]="What would you like to tell us?",["contact.message"]="Message",["contact.messagePlaceholder"]="Tell us about a place, experience or question...",["contact.sendButton"]="Send message",["contact.successTitle"]="Got it.",["contact.success"]="We saved the message. If the email is real, we will reply when we see it.",["contact.location"]="Debar Maalo, Skopje",["contact.locationText"]="There is no sign on the door. Call or write first.",
            ["destinations.title"]="Destinations",["destinations.heroLabel"]="Explore Macedonia",["destinations.heroTitle"]="Four places<br />with the road included.",["destinations.heroText"]="Four places we have actually written up: a village, a mountain, a lake and a canyon near the city.",["destinations.label"]="Our destinations",["destinations.heading"]="Open a place<br />before you go.",["destinations.intro"]="Open one if you want the road and the season, not just the photo.",["destinations.difficulty"]="Difficulty",["destinations.duration"]="Duration",["destinations.bestSeason"]="Best season",["destinations.activities"]="Activities",["destinations.gettingThere"]="Getting there",["destinations.overview"]="Overview",["destinations.back"]="Back to destinations",["destinations.explore"]="Explore destination",
            ["experiences.title"]="Experiences",["experiences.heroLabel"]="EXPERIENCES",["experiences.heroTitle"]="Four ways<br /><em>to spend a day.</em>",["experiences.heroText"]="Four day plans. They are ideas for getting there yourself, not tickets.",["experiences.label"]="CURATED EXPERIENCES",["experiences.heading"]="Pick one<br />and read the notes.",["experiences.intro"]="Filter them if you already know how much time you have.",["experiences.findLabel"]="FIND YOUR ADVENTURE",["experiences.findTitle"]="What do you have time for?",["experiences.category"]="Category",["experiences.duration"]="Duration",["experiences.difficulty"]="Difficulty",["experiences.any"]="Any",["experiences.adventure"]="Adventure",["experiences.culture"]="Culture",["experiences.food"]="Food & Culture",["experiences.nature"]="Nature",["experiences.short"]="Short",["experiences.day"]="1 day",["experiences.weekend"]="Weekend",["experiences.twoDays"]="2 days",["experiences.none"]="Nothing matched. Clear one of the filters and try again.",["experiences.easy"]="Easy",["experiences.moderate"]="Moderate",["experiences.hard"]="Hard",["experiences.findButton"]="Find my adventure",["experiences.location"]="Location",["experiences.season"]="Season",["experiences.back"]="Back to experiences",
            ["stories.title"]="Stories",["stories.heroLabel"]="The HIDDEN MK journal",["stories.heroTitle"]="Short texts,<br /><em>not a magazine.</em>",["stories.heroText"]="Four short texts. They are not a magazine, just things we kept writing down.",["stories.label"]="Journal",["stories.heading"]="What we wrote<br />after the trips.",["stories.intro"]="Four texts. Villages, food, and why the site is small.",["stories.read"]="Read story",["stories.share"]="Share this story",["stories.keepExploring"]="Keep exploring",["stories.cta"]="There's always<br />more to discover.",
            ["faq.title"]="FAQ",["faq.eyebrow"]="QUESTIONS",["faq.heading"]="Short answers, so you do not have to guess.",["faq.q1"]="What is HIDDEN MK?",["faq.a1"]="Hidden MK is a small site about places in Macedonia. It started as a faculty project.",["faq.q2"]="Do I need a guide to explore these places?",["faq.a2"]="No guide is included. These are day plans you do yourself. A marked trail is more useful than a person walking in front of you.",["faq.q3"]="Are the experiences bookable?",["faq.a3"]="No. Nothing here is a booking. The pages are for planning the day yourself.",["faq.q4"]="When is the best time to explore Macedonia?",["faq.a4"]="For the villages and Pelister, May, June and September. For Prespa and swimming, July and August. Matka works most of the year, except when the road is icy.",["faq.q5"]="Can I recommend a hidden place?",["faq.a5"]="Yes. Use the contact form. A place name and how you got there is enough.",["faq.q6"]="How can I contact HIDDEN MK?",["faq.a6"]="The form on the contact page, or hello@hiddenmk.com. The phone is +389 78 221 640 on weekdays.",["faq.still"]="ONE MORE THING",["faq.ask"]="Write if a page is wrong.",["faq.more"]="Roads close, kitchens close, and we do not go every week.",
            ["legal.label"]="LEGAL",["legal.updated"]="Last updated: October 2026",["privacy.title"]="Privacy Policy",["privacy.hero"]="How HIDDEN MK handles information provided by visitors.",["privacy.1h"]="1. Introduction",["privacy.1"]="Hidden MK is a small student site. This page says what happens if you send the contact form.",["privacy.2h"]="2. Information we collect",["privacy.2"]="If you send the form, we keep your name, email, subject and message in a file on the server so we can reply.",["privacy.3h"]="3. How we use information",["privacy.3"]="Information submitted through the contact form may be used to respond to inquiries, recommendations and questions sent to HIDDEN MK.",["privacy.4h"]="4. Cookies",["privacy.4"]="We use one cookie for the language, and one so the cookie banner does not show again. We do not run ads.",["privacy.5h"]="5. Third-party services",["privacy.5"]="The website may use third-party services for content, analytics, maps or embedded media. These services may have their own privacy policies.",["privacy.6h"]="6. Data security",["privacy.6"]="We take reasonable measures to protect information submitted through the website. However, no method of transmission over the internet can be guaranteed to be completely secure.",["privacy.7h"]="7. Contact",["privacy.7"]="If you have questions about this Privacy Policy, please contact us through the HIDDEN MK contact page.",
            ["terms.title"]="Terms & Conditions",["terms.hero"]="The basic terms for using the HIDDEN MK website.",["terms.1h"]="1. Website purpose",["terms.1"]="Hidden MK is a small site with notes about places in Macedonia. It is not a travel agency and it does not sell trips.",["terms.2h"]="2. Information accuracy",["terms.2"]="We aim to provide useful and accurate information. However, conditions at destinations, opening times, accessibility and other circumstances may change. Visitors should verify important information before travelling.",["terms.3h"]="3. User submissions",["terms.3"]="By submitting information through the contact form, you confirm that the information provided is your own or that you have permission to share it.",["terms.4h"]="4. Intellectual property",["terms.4"]="Website content, branding, text and design elements created for HIDDEN MK are intended for use by the HIDDEN MK platform unless otherwise stated.",["terms.5h"]="5. External links",["terms.5"]="HIDDEN MK may contain links to external websites. We are not responsible for the content, availability or policies of external websites.",["terms.6h"]="6. Responsible exploration",["terms.6"]="Visitors are encouraged to respect nature, local communities, cultural heritage and applicable rules when exploring destinations featured on HIDDEN MK.",["terms.7h"]="7. Changes to these terms",["terms.7"]="HIDDEN MK may update these Terms & Conditions when necessary. The latest version will be published on this page.",
            ["error.title"]="Page Not Found",["error.eyebrow"]="YOU'VE FOUND A HIDDEN PATH",["error.heading"]="This page doesn't exist.",["error.text"]="Looks like you've wandered somewhere even HIDDEN MK hasn't discovered yet.",["error.home"]="Back to home",
            ["destination.1.name"]="Galičnik",["destination.1.region"]="Western Macedonia",["destination.1.category"]="Mountain & Culture",["destination.1.short"]="Stone village above Mavrovo. Check if the road is open.",["destination.1.description"]="Galicnik sits high above Mavrovo, on Bistra. Most of the houses are stone, and a lot of them are empty outside summer. The famous day is the Galichka svadba in July. On a normal weekend the village is quieter, which we prefer.",["destination.1.road"]="From Skopje, go toward Gostivar and then Mavrovo. From Mavrovo the road up is narrow. In winter it can be closed, so check before you leave. There is not much to buy in the village. Eat in Mavrovo or bring food.",["destination.1.difficulty"]="Moderate",["destination.1.duration"]="1–2 days",["destination.1.season"]="Spring – Autumn",["destination.1.a1"]="Mountain hiking",["destination.1.a2"]="Traditional food",["destination.1.a3"]="Photography",["destination.1.a4"]="Cultural experiences",
            ["destination.2.name"]="Pelister",["destination.2.region"]="Bitola",["destination.2.category"]="Nature & Adventure",["destination.2.short"]="Pine forest above Bitola. The peak is a full day.",["destination.2.description"]="Pelister is the mountain above Bitola. The Molika pine is the tree people mention. There are marked trails. The one toward the peak is a real day, not a stop for a photo.",["destination.2.road"]="Bus or car to Bitola, then toward the mountain. Hotel Molika is the usual meeting point. May, June and September are easier than noon in August. The path gets rocky, so shoes matter.",["destination.2.difficulty"]="Moderate – Hard",["destination.2.duration"]="1–3 days",["destination.2.season"]="Spring – Autumn",["destination.2.a1"]="Hiking",["destination.2.a2"]="Mountain photography",["destination.2.a3"]="Nature walks",["destination.2.a4"]="Camping",
            ["destination.3.name"]="Prespa",["destination.3.region"]="Southwestern Macedonia",["destination.3.category"]="Lake & Nature",["destination.3.short"]="The quieter lake, past Resen.",["destination.3.description"]="Prespa is the lake south of Ohrid, near Resen. It is bigger and quieter. The villages on the shore are small. In summer you can swim. If you care about birds, the pelicans are why people show up with binoculars.",["destination.3.road"]="Through Resen. A car helps a lot. Buses will not drop you at every beach. In winter the shore is windy and empty. Some people like that. Some do not.",["destination.3.difficulty"]="Easy",["destination.3.duration"]="1–2 days",["destination.3.season"]="Spring – Autumn",["destination.3.a1"]="Birdwatching",["destination.3.a2"]="Kayaking",["destination.3.a3"]="Photography",["destination.3.a4"]="Village exploration",
            ["destination.4.name"]="Matka Canyon",["destination.4.region"]="Near Skopje",["destination.4.category"]="Canyon & Adventure",["destination.4.short"]="Canyon on the edge of Skopje. Busy on Sundays.",["destination.4.description"]="Matka is the canyon on the Treska, just outside Skopje. You can walk the path, take a boat to Vrelo cave, or kayak when the rental places are open. Sunday is busy. A weekday morning is better.",["destination.4.road"]="Bus toward Saraj / Matka, or a taxi from the city. The ride is short. The cave depends on the boat, so if you only have an hour, stay on the path. If you take the boat, wear something that can get a bit wet.",["destination.4.difficulty"]="Easy – Moderate",["destination.4.duration"]="Half day – 1 day",["destination.4.season"]="All year",["destination.4.a1"]="Kayaking",["destination.4.a2"]="Hiking",["destination.4.a3"]="Cave exploration",["destination.4.a4"]="Photography",
            ["experience.1.name"]="Sunrise above Mavrovo",["experience.1.category"]="Adventure",["experience.1.description"]="Leave Mavrovo while it is still dark and walk up toward Bistra. A headlamp helps. If the forecast is bad the night before, skip it.\n\nModerate means a steady uphill, not ropes. There is no ticket. Give yourself the morning.",["experience.1.duration"]="1 day",["experience.1.difficulty"]="Moderate",["experience.1.location"]="Mavrovo / Bistra",["experience.1.season"]="Spring – Autumn",["experience.2.name"]="Food around Mavrovo",["experience.2.category"]="Food & Culture",["experience.2.description"]="A day around Mavrovo and the villages above it. This is not a booked lunch with a host. You eat where a place is actually open: pita, cheese, maybe tavche.\n\nSome kitchens are shut on Sunday. Ask before you assume.",["experience.2.duration"]="1 day",["experience.2.difficulty"]="Easy",["experience.2.location"]="Mavrovo villages",["experience.2.season"]="All year",["experience.3.name"]="Lazaropole and Galicnik",["experience.3.category"]="Culture",["experience.3.description"]="A loose weekend for Lazaropole and Galicnik. Sleep in Mavrovo if the houses up in the villages are shut. Easy means walking around, not a long trail.\n\nThe roads are the tiring part, not the walking.",["experience.3.duration"]="Weekend",["experience.3.difficulty"]="Easy",["experience.3.location"]="Lazaropole and Galicnik",["experience.3.season"]="Spring – Autumn",["experience.4.name"]="Two days on Pelister",["experience.4.category"]="Nature",["experience.4.description"]="Two days if you want more than the view from the parking area. Hard means distance and height, not that the marked path is dangerous.\n\nTell someone where you are going. The signal is not always there.",["experience.4.duration"]="2 days",["experience.4.difficulty"]="Hard",["experience.4.location"]="Pelister, above Bitola",["experience.4.season"]="Summer – Autumn"
        },
