            ["nav.home"]="Почетна",["meta.description"]="Hidden MK е мал водич за Галичник, Пелистер, Преспа и Матка. Го пишуваме од Скопје.",["nav.discover"]="Откриј",["nav.experiences"]="Искуства",["nav.destinations"]="Дестинации",["nav.stories"]="Приказни",["nav.about"]="За нас",["nav.contact"]="Контакт",["nav.faq"]="ЧПП",["nav.privacy"]="Политика за приватност",["nav.terms"]="Услови и правила",
