            ["home.eyebrow"]="СКОПЈЕ · ИДЕИ ЗА ВИКЕНД",["home.heroTitleFirst"]="Четири места",["home.heroTitleSecond"]="кои вреди да се посетат.",["home.heroDescription"]="Hidden MK е мала страница за откривање места во Македонија. Засега ви ги претставуваме Галичник, Пелистер, Преспа и Матка, со неколку идеи за излети и кратки приказни.",["home.exploreHidden"]="Откријте ги четирите места",["home.findAdventure"]="Пронајдете идеја за излет",["home.scrollExplore"]="ПРОДОЛЖЕТЕ НАДОЛУ",["home.idea"]="ЗОШТО ГО ПРАВИМЕ ОВА",["home.introTitle"]="Македонија не завршува со Охрид и Старата чаршија.",["home.introDescription"]="Ако имате слободна сабота, вреди да тргнете и подалеку од автопатот. Ги запишавме работите што би сакале да ги знаевме при првата посета: како да стигнете, колку пешачење ве чека и каде да каснете потоа.",["home.ourStory"]="За сајтот",["home.startExploring"]="НА САЈТОТ",["home.discoverDifferentFirst"]="Местата",["home.discoverDifferentSecond"]="што ги откривме.",["home.viewAllDestinations"]="Сите четири места",["home.mountains"]="ПЛАНИНИ",["home.galicnikDescription"]="Камени куќи над Маврово. Патот нагоре е бавен.",["home.wildNature"]="ДИВА ПРИРОДА",["home.pelisterDescription"]="Борова шума и долга прошетка. Понесете вода.",["home.waterNature"]="ВОДА И ПРИРОДА",["home.prespaDescription"]="Помирно од Охрид, ако ви е доста од гужвата.",["home.canyons"]="КАЊОНИ",["home.matkaDescription"]="На околу 20 минути од Скопје. Брод, пештера или само патеката.",["home.explore"]="Погледнете",["home.nextAdventure"]="АКО НЕ СТЕ СИГУРНИ",["home.whereNextFirst"]="Одберете каков",["home.whereNextSecond"]="ден сакате.",["home.adventureDescription"]="Изберете една од опциите десно за да го отворите филтерот. На страницата со излети можете да филтрирате според категорија, времетраење и тежина.",["home.nature"]="Природа",["home.culture"]="Култура",["home.adventure"]="Авантура",["home.foodStories"]="Храна и приказни",["home.travelDifferently"]="НЕ Е ТУРИСТИЧКА ТУРА",["home.goBeyondFirst"]="Превозот го",["home.goBeyondSecond"]="организирате сами.",["home.experienceDescription"]="Ова не е организиран аранжман со водич, туку почетна точка за планирање: каде да одите, колку време ви треба и дали излетот е соодветен ако не сте навикнати на планинарење секој викенд.",["home.curatedExperiences"]="Идеи за излет",["home.localGuides"]="Практични насоки",["home.authenticStories"]="Приказни од терен",["home.ofMany"]="од многуте",["home.stories"]="приказни",["home.hiddenPlaces"]="места на страницата",["home.guides"]="локални водичи",["home.uniqueExperiences"]="идеи за излет",["home.country"]="земја за откривање",["home.fromJournal"]="ОД НАШИТЕ БЕЛЕШКИ",["home.storiesRoadFirst"]="Од нашите",["home.storiesRoadSecond"]="патни белешки.",["home.readAllStories"]="Сите приказни",["home.travelGuide"]="БЕЛЕШКИ · 5 МИН",["home.localStories"]="СЕЛА · 4 МИН",["home.food"]="ХРАНА · 4 МИН",["home.readStory"]="Прочитајте ја приказната",["home.story1"]="7 места што им ги препорачуваме на пријателите",["home.story2"]="Селата над Маврово",["home.story3"]="Пет јадења и каде се јадат",["home.yourStory"]="АКО СТЕ ВО СКОПЈЕ",["home.readyToDiscoverFirst"]="Матка е одлично",["home.readyToDiscoverSecond"]="место за почеток.",["home.finalDescription"]="Матка е блиску до градот. За другите три места ќе ви треба малку повеќе време.",["home.planAdventure"]="Контакт",
            ["discover.eyebrow"]="ОД КАДЕ ДА ПОЧНЕТЕ",["discover.title"]="Четири идеи за излет.",["discover.subtitle"]="Изберете што ве интересира и разгледајте ги предлозите.",["discover.beyond"]="НА ОВОЈ САЈТ",["discover.looking"]="Што ви се прави?",["discover.lookingText"]="Од овие категории можете да стигнете до места, приказни или идеи за излет. Преку нашата страница не се прават резервации.",["discover.nature"]="Природа",["discover.natureText"]="Планини, езера, шуми, пештери и пејзажи што вреди да се истражат.",["discover.exploreNature"]="Видете ги местата во природа",["discover.culture"]="Култура",["discover.cultureText"]="Села, традиции, историја и приказни што се пренесуваат од генерација на генерација.",["discover.discoverCulture"]="Видете ги селата",["discover.food"]="Храна и локален живот",["discover.foodText"]="Традиционални јадења, локални производители и луѓето што ја чуваат македонската кујна.",["discover.taste"]="Видете ја храната",["discover.adventure"]="Авантура",["discover.adventureText"]="Планинарење, кајакарење и кампување за љубопитните патници.",["discover.findAdventure"]="Видете ги излетите",["discover.how"]="КАКО ДА ПОЧНЕТЕ",["discover.howTitle"]="Ние обично планираме вака.",["discover.howText"]="Не ви треба профил и нема онлајн плаќање.",["discover.step1"]="Изберете што ви одговара",["discover.step1Text"]="Природа, село, локална храна или подолга прошетка.",["discover.step2"]="Проверете ги практичните информации",["discover.step2Text"]="Како се стигнува, колку време е потребно и дали се очекува гужва во недела.",["discover.step3"]="Тргнете или сменете го планот",["discover.step3Text"]="Ако нема резултати, отстранете еден од филтрите и обидете се повторно.",["discover.start"]="МЕСТАТА",["discover.places"]="Четирите места што ги опишавме.",["discover.viewAll"]="Погледнете ги сите дестинации",["discover.finalEyebrow"]="ИЛИ БЕЗ МНОГУ ЧИТАЊЕ",["discover.finalTitle"]="Употребете го филтерот.",["discover.finalText"]="Филтрирајте според категорија, времетраење и тежина. Филтерот ги пребарува четирите идеи за излет.",
["story.1.title"]="7 места што навистина би им ги препорачале на пријателите",["story.1.category"]="Белешки",["story.1.excerpt"]="За четири места веќе имаме посебни страници. Другите три сè уште се на нашата листа.",["story.1.author"]="Редакција на HIDDEN MK",["story.1.date"]="12 септември 2026",["story.1.content"]="Оваа листа започна како белешка во телефонот. Не е целосен водич, туку неколку места што вреди да ги посетите.\n\n1. Галичник, над Маврово. Во јули се одржува Галичката свадба, но и обичен викенд е доволен за посета. Патот од Маврово е тесен.\n\n2. Лазарополе е во близина и е одлично за лежерна прошетка. Има голема црква и прекрасен поглед кон долината.\n\n3. Јанче е помало село каде што вреди да застанете заради погледот. Не очекувајте ресторан на секој чекор.\n\n4. Кокино, во близина на Куманово. До локалитетот се стигнува со кратка прошетка по карпест рид. Во лето најдобро е да одите рано.\n\n5. Манастирот Зрзе се наоѓа на карпа во близина на Прилеп. До него може да се стигне и со обичен автомобил.\n\n6. Мариово, јужно од Прилеп. Очекувајте села, полиња и долги растојанија меѓу местата. Добро е да понесете храна.\n\n7. Кратово. Градот е познат по своите кули и кањонот веднаш под него. За посета од Скопје ви е доволна половина ден.\n\nЗасега имаме посебни страници за Галичник, Пелистер, Преспа и Матка. За другите места имаме само белешки, додека повторно не ги посетиме.",["story.2.title"]="Селата над Маврово",["story.2.category"]="Локални приказни",["story.2.excerpt"]="Одете во Галичник за камените куќи, а во Лазарополе ако сакате да шетате без однапред испланирана рута.",["story.2.author"]="Елена Петрова",["story.2.date"]="28 август 2026",["story.2.content"]="Често ги препорачуваме истите две села, па луѓето потоа нè прашуваат и за трето.\n\nГаличник е познат по камените куќи и по Галичката свадба во јули. Надвор од деновите на свадбата, многу куќи се затворени, што е сосема нормално. Не планирајте дека таму сигурно ќе најдете место за вечера.\n\nВо Лазарополе можете убаво да прошетате. Црквата лесно се забележува, а погледот кон долината е една од главните причини за посета. За ручек можете да се вратите во Маврово.\n\nЈанче е добра дополнителна станица ако ви остане време пред стемнување. Селото е мало, па не очекувајте сè да биде отворено.\n\nЗа ноќевање најпрактично е да изберете сместување во Маврово, освен ако веќе немате договорено престој во некое од селата. Патот нагоре често трае подолго отколку што изгледа на мапата.",["story.3.title"]="Пет јадења и каде се јадат",["story.3.category"]="Храна",["story.3.excerpt"]="Не е рангирање на ресторани, туку преглед на јадењата што често се нарачуваат и на краиштата каде што ќе ги најдете.",["story.3.author"]="Ана Стојановска",["story.3.date"]="14 август 2026",["story.3.content"]="Не издвојуваме „најдобар“ ресторан. Ова се неколку јадења и краиштата во кои најчесто ќе ги сретнете.\n\nТавче гравче лесно ќе најдете во Скопје. Се подготвува од грав во земјено тавче. Едноставно, секојдневно јадење - и токму затоа вреди да се спомене.\n\nАјварот најчесто се подготвува во септември, кога се печат пиперките. Купената тегла не може целосно да го замени свежо подготвениот ајвар.\n\nЗелник и други пити може да најдете во пекарниците покрај патот кон Маврово. Ако наидете на свежи, купете си - во следното село можеби нема да ги има.\n\nПастрмајлијата најмногу се поврзува со Штип и Велес. Не очекувајте да ја најдете во секое планинско село.\n\nШопска салата и печени пиперки се добар избор во локално ресторанче покрај патот, особено кога ќе пристигнете гладни, а дневното мени веќе е потрошено.",["story.4.title"]="Зошто го правиме овој сајт",["story.4.category"]="HIDDEN MK",["story.4.excerpt"]="Сè започна како факултетски проект. На крајот ги задржавме местата што навистина би им ги препорачале на пријателите.",["story.4.author"]="Редакција на HIDDEN MK",["story.4.date"]="30 јули 2026",["story.4.content"]="Сајтот го направивме како факултетски проект, а потоа ги задржавме местата на кои навистина би испратиле пријател. Ова не е страница за резервации.\n\nАко некоја страница е кратка, тоа е затоа што досега сме биле таму само еднаш. Ако патот е затворен или некое место за јадење не работи, пишете ни преку формуларот за контакт.",
            ["about.title"]="Белешки од викендите поминати надвор од Скопје.",["about.eyebrow"]="ЗА САЈТОТ",["about.intro"]="Hidden MK започна како факултетски проект. Избравме места во Македонија што лесно може да ги пропуштите ако ги посетувате само најпознатите дестинации.",["about.storyEyebrow"]="НАШАТА ПРИКАЗНА",["about.storyTitle"]="Ни здодеаја страниците што го покажуваат само погледот.",["about.story1"]="Живееме во Скопје. Повеќето излети што ги предлагаме може да се направат за еден ден или за викенд, со автобус или автомобил.",["about.story2"]="Страниците намерно се кратки. Наместо долг опис на пејзажот, сакаме да ви кажеме како да стигнете до местото.",["about.story3"]="Ако знаете место што сме го пропуштиле, пишете ни преку формуларот за контакт. Пораките ги читаме лично.",["about.philosophy"]="КАКО ПИШУВАМЕ",["about.philosophyText"]="Запишете го она што сте го откриле.<br />Објаснете како се стигнува.<br />Не измислувајте детали за да звучи подобро.",["about.values"]="ШТО ИМА ОВДЕ",["about.moreThan"]="Што всушност ќе најдете.",["about.valuesIntro"]="Ова не е целосен водич низ Македонија, туку збирка од страниците што досега сме ги подготвиле.",["about.value1Title"]="Конкретни места",["about.value1"]="Засега имаме четири дестинации. Нова страница додаваме откако ќе го посетиме местото или ќе ги провериме информациите за патот.",["about.value2Title"]="Кратки текстови",["about.value2"]="Неколку кратки текстови за селата и локалната храна.",["about.value3Title"]="Чувајте го местото",["about.value3"]="Ако патеката е обележана, движете се по неа. Матка и онака знае да биде преполна во недела.",["about.idea"]="ЗАСЕГА",["about.ideaTitle"]="Четири места, четири идеи за излет и четири приказни.",["about.ideaText"]="Ако живеете во Македонија, дел од овие места веројатно веќе ви се познати. Нашите страници сепак може да ви послужат како потсетник за патот и најдобрата сезона за посета. Ако сте во Скопје и имате само неколку часа, почнете со Матка.",
            ["team.title"]="Нашиот тим",["team.eyebrow"]="КОЈ ГО ПИШУВА САЈТОТ",["team.heading"]="Тимот",["team.intro"]="Четворица сме од Скопје и ги поделивме страниците меѓу себе.",["team.label"]="НАШИОТ ТИМ",["team.subtitle"]="Кој што подготвува.",["team.role1"]="ГИ ПИШУВА ТЕКСТОВИТЕ",["team.bio1"]="Елена ги пишува повеќето текстови за селата. Живее во Скопје и оди во Галичник кога патот е прооден.",["team.role2"]="ПАТЕКИ И ПРОШЕТКИ",["team.bio2"]="Марко ги проверува пешачките патеки. Кога пишува дека нешто е со средна тежина, мисли на добра обувка и малку кондиција, не на опрема за качување.",["team.role3"]="СТРАНИЦИ ЗА ХРАНА",["team.bio3"]="Ана ги подготвува текстовите за храна. Повеќе ја интересира потеклото на јадењата отколку составувањето ранг-листи.",["team.role4"]="ФОТОГРАФИИ",["team.bio4"]="Давид се грижи за фотографиите. Дел од нив се наши, а дел сè уште се преземени од Wikimedia Commons.",["team.name1"]="Елена Петрова",["team.name2"]="Марко Илиев",["team.name3"]="Ана Стојановска",["team.name4"]="Давид Николов",["team.join"]="ЗНАЕТЕ МЕСТО?",["team.joinTitle"]="Испратете ни ја препораката.",["team.joinText"]="Ако информациите за патот, храната или работното време не се точни, кажете ни. Подобро да ја поправиме страницата отколку да тврдиме нешто што не е точно.",["team.joinButton"]="Испратете ни порака",
            ["contact.title"]="Контакт",["contact.eyebrow"]="ПИШЕТЕ НИ",["contact.hero"]="Имате прашање, забележавте грешка или сакате да ни препорачате место?",["contact.heroText"]="Пораките од формуларот пристигнуваат директно кај нас. Ги читаме во работните денови.",["contact.label"]="КОНТАКТ СО HIDDEN MK",["contact.heading"]="Истите луѓе што ги пишуваат страниците ќе ви одговорат.",["contact.text"]="Може да ни пишете и на е-пошта. На телефон сме достапни во работните денови, освен кога сме на пат.",["contact.email"]="Е-пошта",["contact.based"]="Локација",["contact.available"]="Достапни сме",["contact.hours"]="Понеделник – петок, 10:00–16:00 часот",["contact.phone"]="Телефон",["contact.phoneNumber"]="+389 78 221 640",["contact.errName"]="Внесете го вашето име.",["contact.errEmail"]="Внесете ја вашата е-пошта.",["contact.errEmailBad"]="Внесената е-пошта не изгледа исправно.",["contact.errMessage"]="Внесете порака.",["contact.errShort"]="Пораката треба да содржи најмалку 10 знаци.",["contact.follow"]="СОЦИЈАЛНИ МРЕЖИ",["contact.send"]="ИСПРАТЕТЕ ПОРАКА",["contact.formHeading"]="Испратете ни порака",["contact.name"]="Вашето име",["contact.emailPlaceholder"]="you@example.com",["contact.subject"]="Предмет",["contact.subjectPlaceholder"]="За што сакате да ни пишете?",["contact.message"]="Порака",["contact.messagePlaceholder"]="Пишете ни за некое место, излет или прашање...",["contact.sendButton"]="Испрати порака",["contact.successTitle"]="Пораката е примена.",["contact.success"]="Ја зачувавме вашата порака. Ако е-поштата е точна, ќе ви одговориме штом ја прочитаме.",["contact.location"]="Дебар Маало, Скопје",["contact.locationText"]="Нема табла на вратата, затоа јавете се или пишете ни пред да дојдете.",
            ["destinations.title"]="Дестинации",["destinations.heroLabel"]="ОТКРИЈТЕ ЈА МАКЕДОНИЈА",["destinations.heroTitle"]="Четири места<br />и сè што треба да знаете за патот.",["destinations.heroText"]="Четири места за кои подготвивме посебни страници: село, планина, езеро и кањон близу градот.",["destinations.label"]="Нашите дестинации",["destinations.heading"]="Запознајте го местото<br />пред да тргнете.",["destinations.intro"]="Отворете ја страницата за да дознаете како се стигнува и кога е најдобро да го посетите местото - не само како изгледа на фотографија.",["destinations.difficulty"]="Тежина",["destinations.duration"]="Времетраење",["destinations.bestSeason"]="Најдобра сезона",["destinations.activities"]="Активности",["destinations.gettingThere"]="Како се стигнува",["destinations.overview"]="Преглед",["destinations.back"]="Назад кон дестинациите",["destinations.explore"]="Погледнете ја дестинацијата",
            ["experiences.title"]="Искуства",["experiences.heroLabel"]="ИСКУСТВА",["experiences.heroTitle"]="Четири идеи<br /><em>како да го поминете денот.</em>",["experiences.heroText"]="Четири идеи за излет што можете сами да ги организирате. Не се потребни билети или резервации преку нас.",["experiences.label"]="ИЗБРАНИ ИСКУСТВА",["experiences.heading"]="Изберете излет<br />и прочитајте ги нашите белешки.",["experiences.intro"]="Филтрирајте ги ако веќе знаете колку време имате.",["experiences.findLabel"]="НАЈДЕТЕ ИЗЛЕТ",["experiences.findTitle"]="Колку време имате на располагање?",["experiences.category"]="Категорија",["experiences.duration"]="Времетраење",["experiences.difficulty"]="Тежина",["experiences.any"]="Сеедно",["experiences.adventure"]="Авантура",["experiences.culture"]="Култура",["experiences.food"]="Храна и култура",["experiences.nature"]="Природа",["experiences.short"]="Кратко",["experiences.day"]="1 ден",["experiences.weekend"]="Викенд",["experiences.twoDays"]="2 дена",["experiences.none"]="Не пронајдовме излет што одговара на избраните филтри. Отстранете еден филтер и обидете се повторно.",["experiences.easy"]="Лесно",["experiences.moderate"]="Средно",["experiences.hard"]="Тешко",["experiences.findButton"]="Прикажи излети",["experiences.location"]="Локација",["experiences.season"]="Сезона",["experiences.back"]="Назад кон идеите",
            ["stories.title"]="Приказни",["stories.heroLabel"]="БЕЛЕШКИ ОД HIDDEN MK",["stories.heroTitle"]="Кратки текстови,<br /><em>без глумење списание.</em>",["stories.heroText"]="Четири кратки приказни за местата, храната и работите што сакавме да ги запишеме по патувањата.",["stories.label"]="Дневник",["stories.heading"]="Што запишавме<br />по нашите излети.",["stories.intro"]="Четири текста за селата, храната и причината зошто овој сајт останува мал.",["stories.read"]="Прочитајте ја приказната",["stories.share"]="Споделете ја приказната",["stories.keepExploring"]="Продолжете понатаму",["stories.cta"]="Има уште многу<br />места за откривање.",
            ["faq.title"]="ЧПП",["faq.eyebrow"]="ПРАШАЊА",["faq.heading"]="Кратки одговори на најчестите прашања.",["faq.q1"]="Што е HIDDEN MK?",["faq.a1"]="Hidden MK е мал сајт за места во Македонија. Почна како проект за факултет.",["faq.q2"]="Дали ми треба водич за овие места?",["faq.a2"]="Не нудиме водичи. Ова се идеи за излети што можете сами да ги организирате. Ако одите на пешачење, придржувајте се до обележаните патеки.",["faq.q3"]="Дали искуствата може да се резервираат?",["faq.a3"]="Не. Преку оваа страница не се прават резервации. Информациите служат за сами да си го испланирате излетот.",["faq.q4"]="Кога е најдобро да се патува низ Македонија?",["faq.a4"]="За селата и Пелистер најпријатни се мај, јуни и септември. За Преспа и капење, најдобри се јули и август. Матка може да се посети речиси цела година, но проверете ги условите ако има мраз.",["faq.q5"]="Можам ли да препорачам скриено место?",["faq.a5"]="Секако! Испратете ни порака преку формуларот за контакт. Доволно е да го наведете името на местото и како сте стигнале до него.",["faq.q6"]="Како можам да го контактирам HIDDEN MK?",["faq.a6"]="Можете да ни пишете преку формуларот на страницата за контакт или на hello@hiddenmk.com. На телефон +389 78 221 640 сме достапни во работните денови.",["faq.still"]="УШТЕ НЕШТО",["faq.ask"]="Пишете ни ако нешто на страницата не е точно.",["faq.more"]="Патиштата понекогаш се затворени, а рестораните не работат секој ден. И ние не можеме да ги проверуваме местата секоја недела.",
            ["legal.label"]="ПРАВНО",["legal.updated"]="Последно ажурирање: октомври 2026",["privacy.title"]="Политика за приватност",["privacy.hero"]="Како HIDDEN MK постапува со информациите што ни ги испраќате.",["privacy.1h"]="1. Вовед",["privacy.1"]="Hidden MK е мал студентски проект. Овде објаснуваме што се случува со информациите што ги испраќате преку формуларот за контакт.",["privacy.2h"]="2. Информации што ги собираме",["privacy.2"]="Кога ќе го испратите формуларот, ги зачувуваме вашето име, е-пошта, предметот и пораката во датотека на серверот за да можеме да ви одговориме.",["privacy.3h"]="3. Како ги користиме информациите",["privacy.3"]="Информациите од формуларот ги користиме за да одговориме на вашите прашања, пораки и препораки испратени до HIDDEN MK.",["privacy.4h"]="4. Колачиња",["privacy.4"]="Користиме едно колаче за да го запомниме избраниот јазик и друго за известувањето за колачиња да не се прикажува повторно. Не прикажуваме реклами.",["privacy.5h"]="5. Услуги од трети страни",["privacy.5"]="Веб-страницата може да користи услуги од трети страни за содржина, аналитика, мапи или вградени медиуми. Овие услуги може да имаат сопствени политики за приватност.",["privacy.6h"]="6. Безбедност на податоците",["privacy.6"]="Преземаме разумни мерки за да ги заштитиме информациите што ни ги испраќате преку страницата. Сепак, преносот на податоци преку интернет никогаш не може да се гарантира како целосно безбеден.",["privacy.7h"]="7. Контакт",["privacy.7"]="Ако имате прашање за оваа политика, пишете ни преку страницата за контакт.",
            ["terms.title"]="Услови и правила",["terms.hero"]="Основните правила за користење на веб-страницата HIDDEN MK.",["terms.1h"]="1. Цел на веб-страницата",["terms.1"]="Hidden MK е мала страница со информации за места во Македонија. Не сме туристичка агенција и не продаваме туристички аранжмани.",["terms.2h"]="2. Точност на информациите",["terms.2"]="Се трудиме информациите да бидат корисни и точни. Сепак, условите на терен, работното време и пристапноста може да се променат. Проверете ги важните информации пред да тргнете.",["terms.3h"]="3. Она што го испраќате",["terms.3"]="Со испраќањето информации преку формуларот потврдувате дека се ваши или дека имате дозвола да ги споделите.",["terms.4h"]="4. Интелектуална сопственост",["terms.4"]="Текстовите, визуелниот идентитет и дизајнот создадени за HIDDEN MK се наменети за користење на оваа платформа, освен ако не е наведено поинаку.",["terms.5h"]="5. Надворешни врски",["terms.5"]="HIDDEN MK може да содржи врски до надворешни веб-страници. Не сме одговорни за нивната содржина, достапност или политики.",["terms.6h"]="6. Одговорно истражување",["terms.6"]="При посетата на местата претставени на HIDDEN MK, почитувајте ја природата, локалните заедници, културното наследство и правилата што важат на самото место.",["terms.7h"]="7. Промени на условите",["terms.7"]="HIDDEN MK може повремено да ги ажурира овие услови. Најновата верзија ќе биде објавена на оваа страница.",
            ["error.title"]="Страницата не е пронајдена",["error.eyebrow"]="ЗАСКИТАВТЕ НА ПОГРЕШНА АДРЕСА",["error.heading"]="Ја нема оваа страница.",["error.text"]="Оваа страница не постои. Вратете се на почетната страница или изберете друга опција од менито.",["error.home"]="Назад на почетната",
            ["destination.1.name"]="Галичник",["destination.1.region"]="Западна Македонија",["destination.1.category"]="Планина и култура",["destination.1.short"]="Камено село над Маврово. Проверете дали патот е отворен.",["destination.1.description"]="Галичник се наоѓа високо над Маврово, на планината Бистра. Познат е по камените куќи, од кои многу се празни надвор од летната сезона. Најпознат настан е Галичката свадба во јули. Во обичен викенд селото е многу помирно - токму тоа ни се допаѓа.",["destination.1.road"]="Од Скопје тргнете кон Гостивар, а потоа кон Маврово. Патот од Маврово до Галичник е тесен, а во зима може да биде затворен, затоа проверете ги условите пред да тргнете. Во селото има малку продавници, па најдобро е да јадете во Маврово или да понесете храна.",["destination.1.difficulty"]="Средно",["destination.1.duration"]="1–2 дена",["destination.1.season"]="Пролет – есен",["destination.1.a1"]="Планинарење",["destination.1.a2"]="Традиционална храна",["destination.1.a3"]="Фотографија",["destination.1.a4"]="Културни искуства",
            ["destination.2.name"]="Пелистер",["destination.2.region"]="Битола",["destination.2.category"]="Природа и авантура",["destination.2.short"]="Борова шума над Битола. До врвот се оди цел ден.",["destination.2.description"]="Пелистер е планината над Битола, позната по моликата - реткиот петоигличест бор. Има неколку обележани патеки, но искачувањето до врвот е целодневна тура, а не кратка прошетка за фотографија.",["destination.2.road"]="До Битола можете да стигнете со автобус или автомобил, а потоа да продолжите кон планината. Хотел „Молика“ е честа почетна точка за посетителите. Мај, јуни и септември обично се попријатни за пешачење од жешките августовски пладниња. Дел од патеките се каменести, па носете соодветни обувки.",["destination.2.difficulty"]="Средно – тешко",["destination.2.duration"]="1–3 дена",["destination.2.season"]="Пролет – есен",["destination.2.a1"]="Планинарење",["destination.2.a2"]="Планинска фотографија",["destination.2.a3"]="Прошетка во шума",["destination.2.a4"]="Кампување",
            ["destination.3.name"]="Преспа",["destination.3.region"]="Југозападна Македонија",["destination.3.category"]="Езеро и природа",["destination.3.short"]="Помирното езеро, по патот за Ресен.",["destination.3.description"]="Преспанското Езеро се наоѓа јужно од Охрид, во близина на Ресен. Пределот е помирен, а селата покрај брегот се мали. Во лето може да се капете, а љубителите на птици доаѓаат и за да ги набљудуваат пеликаните.",["destination.3.road"]="До Преспа се стигнува преку Ресен, а автомобилот е најпрактична опција. Автобусите не застануваат кај секоја плажа. Во зима брегот е ветровит и тивок - некому тоа му одговара, а некому не.",["destination.3.difficulty"]="Лесно",["destination.3.duration"]="1–2 дена",["destination.3.season"]="Пролет – есен",["destination.3.a1"]="Набљудување птици",["destination.3.a2"]="Кајакарење",["destination.3.a3"]="Фотографија",["destination.3.a4"]="Шетање низ селата",
            ["destination.4.name"]="Кањон Матка",["destination.4.region"]="Крај Скопје",["destination.4.category"]="Кањон и авантура",["destination.4.short"]="Кањон до Скопје. Во недела има гужва.",["destination.4.description"]="Матка е кањон на реката Треска, веднаш надвор од Скопје. Можете да прошетате покрај реката, да се качите на брод до пештерата Врело или да изнајмите кајак кога работат пунктовите за изнајмување. Во недела обично има гужва, па подобро е да дојдете наутро во работен ден.",["destination.4.road"]="До Матка можете да стигнете со автобус кон Сарај или со такси од Скопје. Возењето е кратко. За посета на пештерата Врело ви треба брод, па ако имате само еден час, прошетајте по патеката покрај реката. Ако одите со брод, облечете нешто што може да се намокри.",["destination.4.difficulty"]="Лесно – средно",["destination.4.duration"]="Половина ден – 1 ден",["destination.4.season"]="Цела година",["destination.4.a1"]="Кајакарење",["destination.4.a2"]="Планинарење",["destination.4.a3"]="Пештерата Врело",["destination.4.a4"]="Фотографија",
            ["experience.1.name"]="Изгрејсонце над Маврово",["experience.1.category"]="Авантура",["experience.1.description"]="Тргнете од Маврово пред изгрејсонце и пешачете кон Бистра. Ламба ќе ви биде од корист. Ако прогнозата е лоша вечерта претходно, подобро одложете го излетот.\n\nСредна тежина значи постојано искачување, но без потреба од јажиња или опрема за качување. Не се плаќа влезница. Одвојте го целото утро за оваа тура.",["experience.1.duration"]="1 ден",["experience.1.difficulty"]="Средно",["experience.1.location"]="Маврово / Бистра",["experience.1.season"]="Пролет – Есен",["experience.2.name"]="Јадење околу Маврово",["experience.2.category"]="Храна и култура",["experience.2.description"]="Поминете еден ден во Маврово и околните села. Ова не е организиран ручек кај домаќин - ќе јадете таму каде што ќе најдете отворено место. Побарајте пита, сирење или тавче гравче.\n\nНекои ресторани не работат во недела, па проверете однапред наместо да претпоставувате дека ќе бидат отворени.",["experience.2.duration"]="1 ден",["experience.2.difficulty"]="Лесно",["experience.2.location"]="Селата кај Маврово",["experience.2.season"]="Цела година",["experience.3.name"]="Лазарополе и Галичник",["experience.3.category"]="Култура",["experience.3.description"]="Испланирајте лежерен викенд за посета на Лазарополе и Галичник. Ако сместувањето во селата не е достапно, преноќете во Маврово. Лесна тура овде значи прошетка низ селата, а не долго планинарење.\n\nПовеќе ќе ве измори возењето меѓу местата отколку самото пешачење.",["experience.3.duration"]="Викенд",["experience.3.difficulty"]="Лесно",["experience.3.location"]="Лазарополе и Галичник",["experience.3.season"]="Пролет – Есен",["experience.4.name"]="Два дена на Пелистер",["experience.4.category"]="Природа",["experience.4.description"]="Одвојте два дена за Пелистер ако сакате да ја истражите планината, а не само да уживате во погледот од паркингот. Ознаката „тешко“ се однесува на должината и висинската разлика, а не значи дека обележаната патека е опасна.\n\nКажете некому по која патека планирате да одите. На планината нема мобилен сигнал насекаде.",["experience.4.duration"]="2 дена",["experience.4.difficulty"]="Тешко", ["experience.4.location"]="Пелистер, над Битола", ["experience.4.season"]="Лето – Есен"
        }
    };

    public string Get(string key)
    {
        var language = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
        if (!_translations.TryGetValue(language, out var translations)) translations = _translations["en"];
        return translations.TryGetValue(key, out var value) ? value : key;
    }
}
